import React from 'react';
import './App.css';

// Örnek ürün verisi
const products = [
  {
    name: '3D Kaktüs Kalemlik',
    image: 'https://images.unsplash.com/photo-1519125323398-675f0ddb6308?auto=format&fit=crop&w=400&q=80',
    link: 'https://dolap.com/urun/1',
  },
  {
    name: '3D Mini Vazo',
    image: 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=400&q=80',
    link: 'https://dolap.com/urun/2',
  },
  {
    name: '3D Dekoratif Lamba',
    image: 'https://images.unsplash.com/photo-1465101046530-73398c7f28ca?auto=format&fit=crop&w=400&q=80',
    link: 'https://dolap.com/urun/3',
  },
];

function App() {
  return (
    <div className="App">
      <header className="pine3d-header">
        <span role="img" aria-label="pine tree" className="pine3d-logo">🌲</span>
        <h1>Pine3D</h1>
        <p>3D Yazıcı ile Üretilmiş Özel Tasarımlar</p>
      </header>
      <main>
        <h2>Ürünlerimiz</h2>
        <div className="product-gallery">
          {products.map((product, idx) => (
            <div className="product-card" key={idx}>
              <img src={product.image} alt={product.name} className="product-image" />
              <h3>{product.name}</h3>
              <a href={product.link} target="_blank" rel="noopener noreferrer" className="dolap-link">
                Dolap'ta Satın Al
              </a>
            </div>
          ))}
        </div>
      </main>
      <footer className="pine3d-footer">
        <p>Bizi Dolap'ta takip edin: <a href="https://dolap.com/magaza/pine3d" target="_blank" rel="noopener noreferrer">dolap.com/magaza/pine3d</a></p>
        <p>© {new Date().getFullYear()} Pine3D</p>
      </footer>
    </div>
  );
}

export default App;
